<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserInvitation\Domain\ValueObject\Accessor\UserInvitationExpiredAtAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserInvitationExpiredAtAccessor trait.
 *
 * Covers null default, string/VO assignment via withExpiredAt,
 * getExpiredAt/expiredAt accessors, and isExpiredAtChanged with/without original.
 */
class UserInvitationExpiredAtAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withExpiredAt creates a new instance with the ExpiredAt set
     * from a string value, and getExpiredAt returns the primitive string.
     */
    public function testWithExpiredAtFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserInvitationExpiredAtAccessorUnitTest();

        // Act
        $result = $holder->withExpiredAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->getExpiredAt());
    }
    /**
     * Asserts that withexpiredAt has access to the value object
     * from a string value, and getExpiredAt returns the primitive string.
     */
    public function testWithExpiredAtFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserInvitationExpiredAtAccessorUnitTest();

        // Act
        $result = $holder->withExpiredAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->expiredAt()->value());
    }
    public function testChangedExpiredAt(): void
    {
        // Arrange
        $holder = new ImplWithUserInvitationExpiredAtAccessorUnitTest()->withExpiredAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $original = $holder->withExpiredAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $same = $holder->withExpiredAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $modified = $holder->withExpiredAt((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')));

        // Act
        $withSame = $original->isExpiredAtChanged($same);
        $withDiferent = $original->isExpiredAtChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserInvitationExpiredAtAccessorUnitTest
{
    use UserInvitationExpiredAtAccessor;
}
